// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address target, bytes calldata data) public {
        vm.assume(target != address(c));
        vm.assume(amount <= address(c).balance);
        Neutral callee = new Neutral();
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        c.sendMoney(address(callee), 0, data);
        assertTrue(address(c).balance == balanceBefore);
    }
}

contract Neutral {
    fallback() external payable {}
}
